class Register:
    """
    This is the base Register class. All default registers (fg, bg, ef, rs) are created from this class. You can use it to create your own custom registers.

    Attributes:
        renderfuncs (Renderfuncs): A dictionary that stores rendering functions for 8-bit colors and RGB colors.
        is_muted (bool): A flag indicating whether the register is muted, which means it will return an empty string regardless of the input.
        eightbit_call (Callable[[int], str]): A lambda function to handle 8-bit color codes.
        rgb_call (Callable[[int, int, int], str]): A lambda function to handle RGB colors.

    Examples:
        >>> reg = Register()
        >>> print(reg(42))          # Calls the eightbit_call with argument 42
        >>> print(reg('fg'))        # Returns the attribute 'fg' of the register
        >>> print(reg(102, 49, 42)) # Calls the rgb_call with arguments (102, 49, 42)
        >>> reg.is_muted = True     # Mutes the register, all subsequent calls will return an empty string
    """
    def __init__(self):
        self.renderfuncs: Renderfuncs = {}
        self.is_muted = False
        self.eightbit_call = lambda x: x
        self.rgb_call = lambda r, g, b: (r, g, b)

    def __call__(self, *args: Union[int, str], **kwargs) -> str:
        """
        This function is to handle calls such as `fg(42)`, `bg(102, 49, 42)`, `fg('red')`. It returns an empty string if the object is muted. If there's one argument, it checks whether it's an integer (8-bit color code) or a string (attribute name). If there are three arguments, it assumes they represent RGB values for 24-bit color and processes them accordingly.
        """

        # Return empty str if object is muted.
        if self.is_muted:
            return ""

        len_args = len(args)

        if len_args == 1:

            # If input is an 8bit color code, run 8bit render function.
            if isinstance(args[0], int):
                return self.eightbit_call(*args, **kwargs)

            # If input is a string, return attribute with the name that matches input.
            else:
                return getattr(self, args[0])

        # If input is an 24bit color code, run 24bit render function.
        elif len_args == 3:
            return self.rgb_call(*args, **kwargs)

        else:
            return ""
